    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 },
      { sku: 'BRAND-BOOK', qty: 2, discountPercent: 0 },
    ],
  });
  assert.equal(r.ok, true);
  // C-001 is gold (5%)
  assert.equal(r.value.lines[0].discountPercent, 5);
  // Explicit 15%
  assert.equal(r.value.lines[1].discountPercent, 15);
  // Explicit 0%
  assert.equal(r.value.lines[2].discountPercent, 0);
});

test('createInvoice tier discount affects invoice totals', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);

  const totals = invoiceTotals(r.value);
  // 5 * 9500 = 47500, 5% discount = 2375
  // amount after discount = 45125, vat = 45125 * 21 / 100 = 9476.25 -> 9476
  // total = 47500 - 2375 + 9476 = 54601
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 9476);
  assert.equal(totals.total, 54601);
});

test('lineVat calculates VAT on discounted amount', () => {
  // 100 cents, no discount, 21% VAT = 21 cents
  assert.equal(lineVat({ qty: 1, unitPrice: 100, vatRate: 21, discountPercent: 0 }), 21);

  // 100 cents, 10% discount (10 cents off), 90 cents taxable, 21% = 18.9 -> 19 cents
  assert.equal(lineVat({ qty: 1, unitPrice: 100, vatRate: 21, discountPercent: 10 }), 19);

  // 0% VAT
  assert.equal(lineVat({ qty: 5, unitPrice: 9500, vatRate: 0 }), 0);
});

test('lineVat with undefined discountPercent', () => {
  assert.equal(lineVat({ qty: 1, unitPrice: 100, vatRate: 21 }), 21);
});

test('lineVat clamps at 0', () => {
  assert.equal(lineVat({ qty: 1, unitPrice: 100, vatRate: 0 }), 0);
});

test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, vatRate: 21 },
      { qty: 1, unitPrice: 10000, vatRate: 9 },
      { qty: 1, unitPrice: 10000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 30000
  // line 1 vat = 10000 * 21 / 100 = 2100
  // line 2 vat = 10000 * 9 / 100 = 900
  // line 3 vat = 0
  // vat = 3000
  // total = 30000 + 3000 = 33000
  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.vat, 3000);
  assert.equal(totals.total, 33000);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
      { qty: 1, unitPrice: 10000, vatRate: 9, discountPercent: 5 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line 1: 10000, discount 1000, amount 9000, vat = 1890
  // line 2: 10000, discount 500, amount 9500, vat = 855
  // subtotal = 20000, discount = 1500, vat = 2745
  // total = 20000 - 1500 + 2745 = 21245
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 1500);
  assert.equal(totals.vat, 2745);
  assert.equal(totals.total, 21245);
});

